import{AuthService}from"./auth.service.js";export class SaveService{static API_URL="/api/saves";static async getSaves(){const e=AuthService.getToken();if(!e)return{success:!1,saves:[]};const t=await fetch(this.API_URL,{method:"GET",headers:{Authorization:`Bearer ${e}`,"Content-Type":"application/json"}}),a=await t.json();if(!t.ok)throw new Error(a.message||"Failed to retrieve saves");return a}static async getSaveBySlot(e){const t=AuthService.getToken();if(!t)throw new Error("User not authenticated");const a=await fetch(`${this.API_URL}/${e}`,{method:"GET",headers:{Authorization:`Bearer ${t}`,"Content-Type":"application/json"}}),r=await a.json();if(!a.ok)throw new Error(r.message||"Failed to retrieve save");return r}static async saveGame(e,t){const a=AuthService.getToken();if(!a)throw new Error("User not authenticated");const r=await fetch(this.API_URL,{method:"POST",headers:{Authorization:`Bearer ${a}`,"Content-Type":"application/json"},body:JSON.stringify({slotNumber:e,gameState:t})}),o=await r.json();if(!r.ok)throw new Error(o.message||"Failed to save game");return o}static async deleteSave(e){const t=AuthService.getToken();if(!t)throw new Error("User not authenticated");const a=await fetch(`${this.API_URL}/${e}`,{method:"DELETE",headers:{Authorization:`Bearer ${t}`,"Content-Type":"application/json"}}),r=await a.json();if(!a.ok)throw new Error(r.message||"Failed to delete save");return r}}